package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.CulpritVO;

class CulpritValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of culprit of observed issue")
  void test_culprit_value_holder_assign_plain_value() {
    Object holder = new Object();
    CulpritValueHolder<Object> value = new CulpritValueHolder<>(holder);
    Assertions.assertSame(holder, value.culprit("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getCulpritValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getCulprit().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.culpritNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getCulpritValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getCulprit().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of culprit of observed issue")
  void test_culprit_value_holder_assign_value_object() {
    Object holder = new Object();
    CulpritValueHolder<Object> value = new CulpritValueHolder<>(holder);
    CulpritVO vo = CulpritVO.from("one");
    Assertions.assertFalse(value.getCulpritValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.culprit(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getCulpritValue().orElseThrow());
    Assertions.assertSame(holder, value.culprit(Optional.empty()));
    Assertions.assertFalse(value.getCulpritValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.culprit(Optional.of(vo)));
    Assertions.assertSame(vo, value.getCulpritValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of culprit of observed issue against the original")
  void test_culprit_value_holder_read() {
    Object holder = new Object();
    CulpritValueHolder<Object> value = new CulpritValueHolder<>(holder);
    CulpritVO vo = CulpritVO.from("one");
    CulpritVO other = CulpritVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getCulpritValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readCulprit(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readCulprit(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.culprit(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readCulprit(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readCulprit(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of culprit of observed issue")
  void test_culprit_value_holder_unset() {
    Object holder = new Object();
    CulpritValueHolder<Object> value = new CulpritValueHolder<>(holder);
    CulpritVO vo = CulpritVO.from("one");
    value.culprit(vo);
    Assertions.assertSame(holder, value.unsetCulpritIfMatches("culprit_other"));
    Assertions.assertTrue(value.getCulpritValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetCulpritIfMatches("culprit"));
    Assertions.assertFalse(value.getCulpritValue().isPresent(),
        "The field name must clear the value");
    value.culprit(vo);
    Assertions.assertSame(holder, value.unsetCulprit());
    Assertions.assertFalse(value.getCulpritValue().isPresent(), "Unset must clear the value");
  }
}
